package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct {
	TcSensor string
	TcF      decimal.Decimal
}

var WsEofFlag string = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0)
var WsFreeze int64 = 0
var WsCount int64 = 0
var WsFEd string
var WsCEd string

func isInputDone() bool { return WsEofFlag == "Y" }

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

// parse numeric DISPLAY field with implied decimal scale
func parseImplied(s string, scale int32) decimal.Decimal {
	if strings.TrimSpace(s) == "" {
		return decimal.Zero
	}
	s = strings.TrimSpace(s)
	neg := false
	if len(s) > 0 && (s[0] == '-' || s[0] == '+') {
		if s[0] == '-' {
			neg = true
		}
		s = s[1:]
	}
	// collect digits only
	digits := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	// strip leading zeros to avoid huge string? decimal can handle
	d, err := decimal.NewFromString(digits)
	if err != nil {
		return decimal.Zero
	}
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

// store into PIC S9(n)V9(m) by dropping high-order digits
func storePic(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	if val.IsZero() {
		return decimal.Zero
	}
	neg := val.IsNegative()
	mag := val.Abs()
	// ensure scale: truncate toward zero to scale (already rounded before if needed)
	// COBOL stores with truncation except ROUNDED already applied.
	// To mimic high-order drop we work on scaled integer
	mult := decimal.New(1, scale) // 10^scale
	scaled := mag.Mul(mult)
	// truncate toward zero (positive mag so trunc = floor)
	scaledTrunc := scaled.Truncate(0)
	// modulo for high order drop
	modExp := int64(intDigits) + int64(scale)
	mod := decimal.New(1, int32(modExp)) // 10^(intDigits+scale)
	// scaledTrunc % mod
	// decimal has no mod for large, but values fit in int64 (max 999.99 => 99999)
	// use IntPart
	ip := scaledTrunc.IntPart() // fits
	mp := mod.IntPart()
	ip = ip % mp
	// rebuild decimal
	res := decimal.New(ip, -scale)
	if neg {
		res = res.Neg()
		if res.IsZero() {
			res = decimal.Zero
		}
	}
	return res
}

func formatEditedZZ(value decimal.Decimal, intDigits int, fracDigits int, withSign bool) string {
	// withSign means fixed leading sign position
	// handle -0 as zero
	if value.IsZero() {
		value = decimal.Zero
	}
	signChar := ' '
	if withSign {
		if value.Sign() < 0 {
			signChar = '-'
		} else {
			signChar = ' '
		}
	}
	mag := value.Abs()
	// high-order truncation for integer part is done via formatting
	mult := decimal.New(1, int32(fracDigits))
	scaled := mag.Mul(mult)
	// truncate_toward_zero to integer
	scaledInt := scaled.Truncate(0).IntPart()
	if scaledInt < 0 {
		scaledInt = -scaledInt
	}
	powFrac := pow10(fracDigits)
	intPart := scaledInt / powFrac
	fracPart := scaledInt % powFrac
	// high-order drop
	if intDigits > 0 {
		mod := pow10(intDigits)
		intPart = intPart % mod
	}
	// integer string zero padded
	intStr := fmt.Sprintf("%0*d", intDigits, intPart)
	// apply Z suppression: pattern is (intDigits-1) Z's then 9
	// For intDigits=3 pattern ZZ9, first 2 are Z
	chars := []byte(intStr)
	// suppress leading zeros where pattern is Z
	for i := 0; i < intDigits-1; i++ {
		if chars[i] == '0' {
			// check if all previous already suppressed? For ZZ9, any leading zero in Z zone becomes space
			// Need to know if we are still in suppressing region
			// Suppress while we haven't hit a non-zero
			// Determine if any non-space non-zero before? Actually zeros beyond first non-zero stay '0'
			// So scan from left: while we are in Z zone and chars[k]=='0' and all previous suppressed
			// Implement simple: walk left to right, keep suppressed flag
			// We'll need to know if any earlier digit was non-zero (non-suppressed)
			// Use flag
			_ = 0
		}
	}
	// proper suppression with flag
	suppressing := true
	for i := 0; i < intDigits; i++ {
		isZ := i < intDigits-1 // Z positions
		if isZ && suppressing && chars[i] == '0' {
			chars[i] = ' '
		} else {
			suppressing = false
		}
	}
	intFormatted := string(chars)
	fracStr := ""
	if fracDigits > 0 {
		fracStr = fmt.Sprintf("%0*d", fracDigits, fracPart)
		return intFormatted + "." + fracStr
	}
	return intFormatted
}

func formatWSCEd(val decimal.Decimal) string {
	// PIC -ZZ9.99 len 7 : sign + ZZ9.99 (3 int, 2 frac)
	signAndRest := formatEditedZZ(val, 3, 2, true)
	// formatEditedZZ with sign already includes sign? Our helper above returns sign char? Actually we built signChar but not prepended.
	// We need to separate. formatEditedZZ currently returns only int+frac with sign logic not prepended? Let's adjust.
	// In formatEditedZZ we computed signChar but didn't use; we returned only intFormatted.frac
	// So we need to prepend signChar
	// But we already used sign logic inside, need to reconstruct
	// Easiest: recompute here
	if val.IsZero() {
		val = decimal.Zero
	}
	signChar := ' '
	if val.Sign() < 0 {
		signChar = '-'
	}
	mag := val.Abs()
	inner := formatEditedZZ(mag, 3, 2, false)
	return string(signChar) + inner
}

func formatWSFEd(val decimal.Decimal) string {
	// PIC ZZ9.9 len5
	return formatEditedZZ(val, 3, 1, false)
}

func formatUnedited(val int64, digits int) string {
	mod := pow10(digits)
	v := val % mod
	if v < 0 {
		v = -v
	}
	return fmt.Sprintf("%0*d", digits, v)
}

// file handling
var tempFile *os.File
var reader *bufio.Scanner
var currentRec TempRec
var eofReached bool

func openInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		// treat missing as EOF
		eofReached = true
		WsEofFlag = "Y"
		return
	}
	tempFile = f
	reader = bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	reader.Buffer(buf, 1024*1024)
}

func closeInput() {
	if tempFile != nil {
		tempFile.Close()
	}
}

func readPara() {
	if eofReached {
		WsEofFlag = "Y"
		return
	}
	if reader == nil {
		WsEofFlag = "Y"
		return
	}
	if !reader.Scan() {
		WsEofFlag = "Y"
		eofReached = true
		return
	}
	line := reader.Text()
	// Pad with spaces to 8
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	}
	if len(line) > 8 {
		line = line[:8]
	}
	sensor := line[0:4]
	fPart := line[4:8]
	rec := TempRec{}
	rec.TcSensor = sensor
	rec.TcF = parseImplied(fPart, 1)
	currentRec = rec
}

func processPara() {
	// COMPUTE WS-C ROUNDED = (TC-F - 32) *5/9
	thirtyTwo := decimal.NewFromInt(32)
	five := decimal.NewFromInt(5)
	nine := decimal.NewFromInt(9)
	raw := currentRec.TcF.Sub(thirtyTwo).Mul(five).Div(nine)
	// ROUNDED to scale 2
	rounded := raw.Round(2)
	// store trunc high order to S9(3)V99
	WsC = storePic(rounded, 3, 2)

	if WsC.Cmp(decimal.Zero) < 0 {
		WsFreeze = (WsFreeze + 1) % 100 // PIC 99 overflow low-order digits
		// keep value within 0-99 via low-order; simple mod 100
		if WsFreeze < 0 {
			WsFreeze += 100
		}
	}
	WsCount = (WsCount + 1) % 100
	if WsCount < 0 {
		WsCount += 100
	}

	WsFEd = formatWSFEd(currentRec.TcF)
	WsCEd = formatWSCEd(WsC)

	// DISPLAY TC-SENSOR " " WS-F-ED "F " WS-C-ED "C"
	// DISPLAY writes operands concatenated followed by newline to stdout
	fmt.Printf("%s %sF %sC\n", currentRec.TcSensor, WsFEd, WsCEd)
}

func mainPara() {
	openInput()
	readPara()
	for !isInputDone() {
		processPara()
		readPara()
	}
	closeInput()
	// DISPLAY "READINGS: " WS-COUNT " BELOW ZERO: " WS-FREEZE
	// WS-COUNT and WS-FREEZE are PIC 99 zero-padded 2
	cStr := formatUnedited(WsCount, 2)
	fStr := formatUnedited(WsFreeze, 2)
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", cStr, fStr)
}

func main() {
	mainPara()
}

